import sympy as sp

def compute_A(a_list):
    n = len(a_list)
    A = 0
    for x in range(n):
        prod = 1
        for y in range(n):
            if x == y:
                continue
            prod *= (a_list[x] * a_list[y] - 1) / (a_list[x] - a_list[y])
        A += prod
    return A

for n in range(2, 6):
    a = [sp.Symbol(f'a{i}') for i in range(1, n+1)]
    res = compute_A(a)
    print(f"n={n}: {sp.simplify(res)}")

